export function getQuestions(path, locale) {
    return questionSets[path].map((question) => {
        const copy = locale === "en" ? enQuestions[question.id] : koOverrides[question.id];
        if (!copy)
            return question;
        return {
            ...question,
            eyebrow: copy.eyebrow ?? question.eyebrow,
            title: copy.title ?? question.title,
            help: copy.help ?? question.help,
            choices: question.choices.map((choice, index) => ({
                ...choice,
                label: copy.choices?.[index] ?? choice.label,
                redFlag: locale === "en" && choice.redFlag ? englishRedFlags[question.id] ?? choice.redFlag : choice.redFlag,
                opportunity: locale === "en" ? englishChoiceDetails[question.id]?.[index]?.opportunity : choice.opportunity,
                threat: locale === "en" ? englishChoiceDetails[question.id]?.[index]?.threat : choice.threat,
            })),
        };
    });
}
